package diagnostics

import (
	"context"
	"fmt"
	"net"
	"time"

	"dpibypass/internal/strategy"
	"dpibypass/internal/tlsparse"
)

// StrategyConn wraps a net.Conn to intercept the initial outbound application write
// (such as the TLS ClientHello generated by crypto/tls.Client) and execute the configured
// production strategy transformations against the underlying socket.
type StrategyConn struct {
	net.Conn
	ctx            context.Context
	strat          strategy.Strategy
	intercepted    bool
	applied        bool
	isFallback     bool
	fallbackReason string
	chunkCount     int
	bytesSent      int
	writeErr       error
}

// NewStrategyConn wraps underlying connection with the production strategy.
func NewStrategyConn(ctx context.Context, underlying net.Conn, strat strategy.Strategy) *StrategyConn {
	return &StrategyConn{
		Conn:  underlying,
		ctx:   ctx,
		strat: strat,
	}
}

// Write intercepts the first outbound write to apply strategy chunking or record splitting.
// All subsequent writes pass directly to the underlying connection.
func (s *StrategyConn) Write(b []byte) (int, error) {
	if s.intercepted {
		return s.Conn.Write(b)
	}
	s.intercepted = true

	// If no strategy or strategy is "none", forward directly without transformation
	if s.strat == nil || s.strat.Name() == "none" {
		s.applied = false
		s.chunkCount = 1
		n, err := s.Conn.Write(b)
		s.bytesSent = n
		return n, err
	}

	// First write: attempt to parse TLS ClientHello
	limits := tlsparse.DefaultLimits()
	parseRes := tlsparse.ParseClientHello(b, limits)

	if parseRes.Status != tlsparse.StatusParsed || parseRes.Metadata == nil {
		// Non-TLS or malformed ClientHello: forward unchanged without claiming strategy applied
		s.applied = false
		s.isFallback = true
		s.fallbackReason = fmt.Sprintf("initial bytes not parsed as ClientHello (%s)", parseRes.Status)
		n, err := s.Conn.Write(b)
		s.bytesSent = n
		return n, err
	}

	plan, err := s.strat.Plan(s.ctx, b, parseRes.Metadata)
	if err != nil || plan.IsFallback {
		// Strategy planning failed or resulted in fallback to unchanged bytes
		s.applied = false
		s.isFallback = true
		if err != nil {
			s.fallbackReason = fmt.Sprintf("plan error: %v", err)
		} else {
			s.fallbackReason = plan.FallbackReason
		}

		// Forward original bytes unchanged
		fallbackPlan := strategy.ExecutionPlan{
			StrategyName:   "none",
			Chunks:         []strategy.WriteChunk{{Data: b}},
			IsFallback:     true,
			FallbackReason: s.fallbackReason,
		}
		n, writeErr := strategy.Execute(s.ctx, s.Conn, fallbackPlan)
		s.chunkCount = 1
		s.bytesSent = n
		if writeErr != nil {
			s.writeErr = writeErr
			return n, fmt.Errorf("fallback execute failed: %w", writeErr)
		}
		return len(b), nil
	}

	// Plan succeeded: execute the production transformation chunks
	n, writeErr := strategy.Execute(s.ctx, s.Conn, plan)
	s.chunkCount = len(plan.Chunks)
	s.bytesSent = n
	if writeErr != nil {
		s.applied = false
		s.writeErr = writeErr
		return n, fmt.Errorf("strategy execute failed: %w", writeErr)
	}

	s.applied = true
	return len(b), nil
}

// Applied returns whether a strategy transformation (chunk splitting or record splitting)
// was genuinely planned and executed on the wire. Returns false for baseline 'none',
// unchanged forwarding, fallback, or write failures.
func (s *StrategyConn) Applied() bool {
	return s.applied
}

// IsFallback returns true if strategy planning failed or input was non-TLS, resulting in fallback to unchanged bytes.
func (s *StrategyConn) IsFallback() bool {
	return s.isFallback
}

// FallbackReason returns the explanation if fallback occurred.
func (s *StrategyConn) FallbackReason() string {
	return s.fallbackReason
}

// ChunkCount returns the number of discrete write chunks emitted for the initial message.
func (s *StrategyConn) ChunkCount() int {
	return s.chunkCount
}

// BytesSent returns the total bytes emitted across all chunks for the initial message.
func (s *StrategyConn) BytesSent() int {
	return s.bytesSent
}

// SetWriteDeadline delegates to underlying net.Conn.
func (s *StrategyConn) SetWriteDeadline(t time.Time) error {
	return s.Conn.SetWriteDeadline(t)
}

// SetReadDeadline delegates to underlying net.Conn.
func (s *StrategyConn) SetReadDeadline(t time.Time) error {
	return s.Conn.SetReadDeadline(t)
}
